// Authored scenario/debugging/design exercises for Express 5. These acceptance
// scenarios are manual review criteria, not an in-browser execution facility.
const review = (topic, difficulty, slug, title, prompt, objective, requirements, cases, hints, answer, followUp) => ({
    id: `backend-express-${slug}-v1`, career: "Backend Developer", phase: "Express.js", topic,
    title, difficulty, kind: "written", language: "Express 5 technical response",
    estimatedTime: difficulty === "Easy" ? "20–30 minutes" : difficulty === "Medium" ? "35–50 minutes" : "50–75 minutes",
    problemStatement: prompt, simplerProblem: objective,
    learningObjectives: [objective, `Justify the ${topic} contract against both supplied acceptance scenarios.`],
    conceptsToReview: [topic], prerequisites: ["Node.js promises and HTTP request/response basics"],
    requirements, examples: cases.map(([input, output]) => ({input, output, explanation: objective})),
    tests: cases.map(([input, expected], i) => ({name: `Acceptance scenario ${i + 1}`, input, expected})),
    hints, approach: `${hints[0]} ${hints[1]} Trace the specified request through that boundary before evaluating the proposed response.`,
    walkthrough: cases.map(([input, output]) => `${input} → ${output}`).join("\n"),
    solutionCode: answer, solutionLines: answer.split("\n").filter(Boolean),
    completionCriteria: requirements, commonMistakes: [],
    starterCode: "Implementation or diagnosis:\n\nRequest traces and acceptance evidence:\n\nFailure boundaries:\n",
    followUp
});

